    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        left = 0
        ans = 0
        n = len(nums)

        for right in range(n):
            # Check if current left position violates conditions
            if nums[left] % 2 != 0 or nums[left] > threshold or (right > 0 and nums[right] % 2 == nums[right - 1] % 2):
