    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        import bisect

        n = len(nums)
        maxleft = {}  # Maps value -> best sum ending with that value
        i = 0

        while i < n:
            num = nums[i]

            if num in maxleft:
                # Already seen this number, update its best sum
                previdx = bisect.bisect_left(sorted(maxleft.keys()), num)

                if previdx == 0:
                    val = maxleft.get(num, float('-inf'))
                    maxleft[num] = max(val, val + num)
                else:
                    prev_key = list(maxleft.keys())[previdx - 1]
                    prev_val = maxleft[prev_key]
                    maxleft[num] = max(prev_val + num, num)
            else:
                # First time seeing this number
                previdx = bisect.bisect_left(sorted(maxleft.keys()), num)

                if previdx == 0:
                    maxleft[num] = num
                else:
                    prev_key = list(maxleft.keys())[previdx - 1]
                    prev_val = maxleft[prev_key]
                    maxleft[num] = max(prev_val + num, num)

            # Find next position to potentially remove
            nextidx = bisect.bisect_right(sorted(maxleft.keys()), num)
            if nextidx < len(maxleft) and maxleft[list(maxleft.keys())[nextidx]] <= maxleft[num]:
                del maxleft[list(maxleft.keys())[nextidx]]

            i += 1

        return max(maxleft.values()) if maxleft else float('-inf')

